import { useState, useEffect } from "react";
import style from "./Show.module.sass";
import View from "wrappers/View/View";
import { useParams } from "react-router-dom";
import { useNavigate } from "react-router-dom";
import Image from "components/Image/Image";
import cn from "classnames";
import axios from "axios";
import { serverPath } from "BackendServerPath";
import { Icon } from "components/Icon/Icon";
import LoadingCard from "components/LoadingCard/LoadingCard";
import Section from "components/Section/Section";
import ShowCategories from "./Features/ShowCategories/ShowCategories";
import ShowDetails from "./Features/ShowDetails/ShowDetails";
import ShowReviews from "./Features/ShowReviews/ShowReviews";
import ShowActors from "./Features/ShowActors/ShowActors";
import Modal from "components/Modal/Modal";
import AddReview from "components/AddReview/AddReview";
import EditReview from "components/EditReview/EditReview";
import DefaultButton from "components/DefaultButton/DefaultButton";
import Score from "components/Score/Score";
import Date from "components/Date/Date";
import { useAuth } from "wrappers/AuthContext/AuthContext";
import { returnAccessToken } from "utils/Authentication";

function Show() {
  const { isAuth, userData } = useAuth();
  const { slug } = useParams();
  const navigate = useNavigate();
  const [show, setShow] = useState<any>();
  const [loading, setLoading] = useState(false);
  const [addReviewModal, setAddReviewModal] = useState(false);
  const [userReview, setUserReview] = useState<any>();
  const [userReviewModal, setUserReviewModal] = useState(false);
  const [showInLibrary, setShowInLibrary] = useState(false);

  const getShowData = async () => {
    const { accessToken } = await returnAccessToken();
    setLoading(true);
    axios
      .get(`${serverPath}api/shows/${slug}/`, {
        headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : {},
      })
      .then((response) => {
        setShow(response?.data);
        setShowInLibrary(response?.data?.in_library);
        setLoading(false);
      })
      .catch((error) => {
        console.log(error);
        setLoading(false);
        navigate("/");
      });
  };

  useEffect(() => {
    getShowData();
  }, [slug]);

  const addShowToLibrary = async (ID: number) => {
    const { accessToken } = await returnAccessToken();
    axios
      .post(
        `${serverPath}/api/shows/library/add/${ID}/`,
        {},
        {
          headers: accessToken
            ? { Authorization: `Bearer ${accessToken}` }
            : {},
        }
      )
      .then((response) => {
        setShowInLibrary(true);
      })
      .catch((error) => {
        console.log(error);
      });
  };

  const removeShowFromLibrary = async (ID: number) => {
    const { accessToken } = await returnAccessToken();
    console.log(accessToken);
    axios
      .post(
        `${serverPath}/api/shows/library/remove/${ID}/`,
        {},
        {
          headers: accessToken
            ? { Authorization: `Bearer ${accessToken}` }
            : {},
        }
      )
      .then((response) => {
        setShowInLibrary(false);
      })
      .catch((error) => {
        console.log(error);
      });
  };

  const checkIfUserReview = () => {
    show?.has_reviewed &&
      show?.reviews?.map((item: any) => {
        if (item?.author?.id === userData?.id) {
          setUserReview(item);
        }
      });
  };

  useEffect(() => {
    checkIfUserReview();
  }, [show]);

  const getYoutubeEmbededURL = (link: string) => {
    return link?.split("https://www.youtube.com/watch?v=")[1];
  };

  return (
    <View background={true} backButton={true}>
      {loading ? (
        <LoadingCard classname={style.container} spinnerSize={75} />
      ) : (
        <div className={style.container}>
          <div className={style.row}>
            <div className={style.video_and_description}>
              <iframe
                className={style.video}
                src={`https://www.youtube.com/embed/${getYoutubeEmbededURL(
                  show?.youtube_video
                )}?rel=0&iv_load_policy=3&modestbranding=1&autoplay=0&mute=1`}
                title="YouTube video player"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              />
              <Section title="Summary" sectionColor="yellow">
                {show?.description}
              </Section>
            </div>
            <div className={style.info}>
              <div className={style.name}>{show?.name}</div>
              <Image image={show?.image} classname={style.image} />
              <Date date={show?.release_date} />
              <div className={style.separator} />
              <div className={style.score_row}>
                <div className={style.score_text_container}>
                  <div className={style.score_title}>MAX SCORE</div>
                  <div className={style.score_text}>
                    Based on {show?.reviews?.length} reviews
                  </div>
                </div>
                <Score score={show?.score} scale />
              </div>
              <div className={style.separator} />
              <div className={style.score_row}>
                <div className={style.score_text_container}>
                  <div className={style.score_title}>YOUR REVIEW</div>
                  {userReview ? (
                    <DefaultButton
                      text="Your review"
                      onClick={() => setUserReviewModal(true)}
                    />
                  ) : (
                    <div className={style.score_text}>Add your own Review!</div>
                  )}
                </div>
                {userReview ? (
                  <Score score={userReview?.rating} scale />
                ) : (
                  <div
                    className={cn(style.add_score)}
                    onClick={() => setAddReviewModal(true)}
                  >
                    <Icon
                      name={"plus"}
                      className={style.plus_svg}
                      viewBox="0 0 24 24"
                    />
                  </div>
                )}
              </div>
              <div className={style.separator} />
              {isAuth ? (
                showInLibrary ? (
                  <div
                    className={cn(style.library_button, style.blue)}
                    onClick={() => removeShowFromLibrary(show?.id)}
                  >
                    Already in Library
                    <div className={style.remove_text}>Click to remove</div>
                  </div>
                ) : (
                  <div
                    className={cn(style.library_button)}
                    onClick={() => addShowToLibrary(show?.id)}
                  >
                    Add to library
                    <Icon
                      name={"plus"}
                      className={style.plus_svg}
                      viewBox="0 0 24 24"
                    />
                  </div>
                )
              ) : (
                <div
                  className={cn(style.library_button, style.unauthorized)}
                  onClick={() => navigate("/login")}
                >
                  Log in To access Library!
                </div>
              )}
            </div>
          </div>
          <div className={style.separator} />
          <Section title="Genres" sectionColor="blue">
            <ShowCategories data={show?.categories} />
          </Section>
          <div className={style.separator} />
          <Section title="Actors" sectionColor="green">
            <ShowActors data={show?.actors} />
          </Section>
          <div className={style.separator} />
          <Section title="Details" sectionColor="red">
            <ShowDetails
              esrb={show?.ESRB}
              release_date={show?.release_date}
              duration={show?.episode_duration}
              director={show?.director}
              writers={show?.writers}
              production={show?.production}
              episodes={show?.episodes}
            />
          </Section>
          <div className={style.separator} />
          <Section title="Reviews">
            <ShowReviews
              data={show?.reviews}
              userReviewID={userReview?.id}
              openReviewModal={() => setUserReviewModal(true)}
            />
          </Section>
        </div>
      )}

      <Modal setVisible={setAddReviewModal} visible={addReviewModal}>
        <AddReview id={show?.id} url="/api/shows/reviews/create/" />
      </Modal>

      <Modal setVisible={setUserReviewModal} visible={userReviewModal}>
        <EditReview
          data={userReview}
          url="api/shows/review/edit/"
          deleteUrl="api/shows/review/delete/"
        />
      </Modal>
    </View>
  );
}

export default Show;
