interface SvgImagePropsScheme {
  size?: number;
  name?: string;
  rotate?: string;
  viewBox?: string;
  stroke?: string;
  strokeWidth?: number;
  className?: any;
}

const Icon = (props: SvgImagePropsScheme) => {
  const size = props.size ? props.size : 24;
  const name = props.name ? props.name : "heart";
  const viewBox = props.viewBox ? props.viewBox : "";
  const stroke = props.stroke ? props.stroke : "";
  const strokeWidth = props.strokeWidth ? props.strokeWidth : 2;
  const className = props.className ? props.className : "";
  const rotate = props.rotate ? props.rotate : "0deg";

  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      stroke={stroke}
      strokeWidth={strokeWidth}
      className={className}
      style={{ transform: `rotate(${rotate})` }}
    >
      <path d={icons[name as keyof typeof icons]} />
    </svg>
  );
};

export { Icon };
